import json, sys, time
sys.path.insert(0, '.')
from harness import _req as R, login, check, LOG
S = json.load(open('state.json')); ac = S['acc']
T = {k: login(v['email'], v['pw']) for k, v in ac.items() if k in ('drA', 'drB', 'bio', 'pharma', 'caisse', 'compta', 'accueil', 'ide')}
pid, vid, cid, loid = S['pid'], S['vid'], S['cid'], S['loid']
st, active = R('GET', '/api/visits/active', T['drA']); row = next((x for x in active if x.get('id') == vid), {})
print('queue row keys', sorted(row.keys()))
print('queue row', {k: row.get(k) for k in row if 'lert' in k or 'tage' in k or 'riority' in k})
st, res = R('GET', f'/api/lab-orders/patient/{pid}/results', T['drA'])
check('LAB-01', 'Medecin voit le resultat avec son statut (brouillon distingue)', st == 200, [(r.get('analyteName'), r.get('status'), r.get('interpretation')) for r in res] if isinstance(res, list) else res)
st, o = R('GET', f'/api/lab-orders/{loid}', T['bio'])
check('LAB-02', 'Statut de la demande apres resultat brouillon', True, (o.get('status'), [(i.get('examName'), i.get('status')) for i in o.get('items', [])]))
nfs = next(i for i in o['items'] if i['examName'] == 'NFS')
seq = []
for stt in ('SAMPLE_COLLECTED', 'IN_PROGRESS', 'RESULT_AVAILABLE', 'VALIDATED'):
    st, x = R('PATCH', f"/api/lab-orders/{loid}/items/{nfs['id']}/status", T['bio'], {"status": stt}); seq.append((stt, st))
check('LAB-03', 'Cycle d un examen (prelevement -> valide) par items', all(s < 300 for _, s in seq), seq)
st, up = R('POST', '/api/lab-orders/results', T['bio'], {"examRequestNumber": o['examRequestNumber'], "validatorName": "Biologiste Audit", "status": "VALIDATED", "results": [{"analyteName": "Hb", "value": "9.1", "unit": "g/dL", "referenceRange": "13-17", "interpretation": "ABNORMAL"}], "labOrderItemId": nfs['id']})
check('LAB-04', 'Resultat valide televerse', st < 300, st)
st, pr = R('POST', f'/api/consultations/{cid}/prescription', T['drA'], {"items": [{"drugName": "Artemether-Lumefantrine", "dosage": "20/120 mg", "posology": "4 cp x2/j 3 jours", "quantity": "1 boite de 24", "route": "PO", "duration": "3 jours"}]})
check('RX-01', 'Dr A redige l ordonnance (brouillon)', st in (200, 201), (st, pr if st >= 300 else pr.get('status')))
st, sig = R('POST', f'/api/visits/{vid}/close', T['drB'])
check('VIS-01', 'Dr B (non pris en charge) ne peut pas cloturer/signer la visite de Dr A', st >= 400, (st, str(sig)[:200]))
if st >= 400:
    st, cl = R('POST', f'/api/visits/{vid}/close', T['drA'])
    check('VIS-02', 'Dr A cloture la visite (signature consultation + ordonnance)', st < 300, (st, str(cl)[:150]))
st, c = R('GET', f'/api/visits/{vid}/consultation', T['drA'])
check('VIS-03', 'Signataire de la consultation', True, {k: c.get(k) for k in c if 'sign' in k.lower() or 'doctor' in k.lower() or k == 'status'} if isinstance(c, dict) else c)
st, pres = R('GET', f'/api/consultations/{cid}/prescription', T['drA'])
check('RX-02', 'Ordonnance active apres cloture', isinstance(pres, dict) and pres.get('status') == 'ACTIVE', {k: pres.get(k) for k in ('status', 'prescriptionNumber', 'pinCode')} if isinstance(pres, dict) else pres)
st, o = R('GET', f'/api/lab-orders/{loid}', T['bio'])
check('VIS-04', 'Cloture de visite alors qu un examen reste en brouillon : bloquee ou signalee', False, (o.get('status'), [(i.get('examName'), i.get('status')) for i in o.get('items', [])]))
st, pre = R('POST', '/api/invoices/precalculate', T['compta'], {"patientId": pid, "visitId": vid})
items = pre.get('items', []) if isinstance(pre, dict) else []
check('BIL-01', 'Pre-calcul facture : lignes proposees', st == 200, [(i.get('label'), i.get('itemType'), i.get('unitPrice'), i.get('quantity')) for i in items] or (st, pre))
check('BIL-02', 'Les examens de laboratoire apparaissent dans la facture', any('NFS' in (i.get('label') or '') or 'Goutte' in (i.get('label') or '') for i in items), len(items))
q = next((i.get('quantity') for i in items if i.get('itemType') == 'MEDICATION'), None)
check('BIL-03', 'Quantite medicament "1 boite de 24" interpretee correctement', q in (1, 24, '1', '24', 1.0, 24.0), q)
st, inv = R('POST', '/api/invoices', T['accueil'], {"patientId": pid, "visitId": vid})
check('BIL-04', 'Accueil cree la facture de la visite', st in (200, 201), (st, inv if st >= 300 else (inv.get('status'), inv.get('totalAmount'))))
inv_id = inv.get('id')
st, inv2 = R('POST', '/api/invoices', T['compta'], {"patientId": pid, "visitId": vid})
check('BIL-05', 'Deuxieme facture meme visite refusee (complement impossible)', st >= 400, (st, str(inv2)[:150]))
st, regs = R('GET', '/api/cash-registers', T['caisse'])
check('CSH-01', 'Caisse principale disponible sans parametrage', st == 200 and bool(regs), [(r.get('code'), r.get('name')) for r in regs] if isinstance(regs, list) else regs)
st, ss = R('POST', '/api/cash-registers/sessions/open', T['caisse'], {"cashRegisterId": regs[0]['id'] if isinstance(regs, list) and regs else None, "openingBalance": 10000})
check('CSH-02', 'Caissier ouvre la session', st in (200, 201), (st, str(ss)[:150]))
st, cq = R('GET', '/api/invoices/collection-queue', T['caisse'])
check('CSH-03', 'Facture non validee visible dans la file d encaissement', True, (st, inv_id in json.dumps(cq)))
st, pay = R('POST', f'/api/invoices/{inv_id}/payments', T['caisse'], {"amount": 5000, "method": "CASH"})
check('CSH-04', 'Paiement sur facture non validee', True, (st, str(pay)[:200]))
st, val = R('POST', f'/api/invoices/{inv_id}/validate', T['compta'])
check('BIL-06', 'Facturation valide la facture', st < 300, (st, val.get('status') if isinstance(val, dict) else val))
st, cq = R('GET', '/api/invoices/collection-queue', T['caisse'])
check('CSH-03b', 'Facture validee visible dans la file d encaissement', inv_id in json.dumps(cq), st)
st, pay = R('POST', f'/api/invoices/{inv_id}/payments', T['caisse'], {"amount": 5000, "method": "CASH"})
check('CSH-05', 'Paiement partiel apres validation', st < 300, (st, str(pay)[:200]))
st, iv = R('GET', f'/api/invoices/{inv_id}', T['caisse'])
check('CSH-06', 'Statut facture apres paiement partiel', True, {k: iv.get(k) for k in iv if k in ('status', 'totalAmount', 'patientAmount', 'paidAmount', 'collectionStatus', 'patientRemainingAmount', 'remainingAmount')} if isinstance(iv, dict) else iv)
if isinstance(pres, dict) and pres.get('pinCode'):
    st, ver = R('POST', '/api/public/pharmacy/prescriptions/verify', None, {"prescriptionNumber": pres['prescriptionNumber'], "pinCode": pres['pinCode']})
    check('PH-01', 'Verification ordonnance par numero + PIN sans authentification', st == 200, (st, str(ver)[:200]))
    item_id = pres['items'][0]['id']
    body = {"prescriptionNumber": pres['prescriptionNumber'], "pinCode": pres['pinCode'], "pharmacyName": "Pharmacie interne", "pharmacistLicense": "PH-1", "dispensedItems": [{"prescriptionItemId": item_id, "quantityDispensed": 1}]}
    st, d = R('POST', '/api/public/pharmacy/prescriptions/dispense', T['pharma'], body)
    check('PH-02', 'Delivrance sans validation pharmaceutique refusee', st >= 400, (st, str(d)[:150]))
    st, d = R('POST', '/api/public/pharmacy/prescriptions/validate', T['pharma'], {"prescriptionNumber": pres['prescriptionNumber'], "pinCode": pres['pinCode'], "reviewNotes": "RAS"})
    st, d = R('POST', '/api/public/pharmacy/prescriptions/dispense', T['pharma'], body)
    check('PH-03', 'Pharmacien delivre apres validation', st < 300, (st, str(d)[:150]))
    st, stocks = R('GET', '/api/pharmacy/stocks', T['pharma'])
    check('PH-04', 'Stock pharmacie impacte par la delivrance', False, (st, str(stocks)[:150]))
S.update({"inv_id": inv_id, "pres": pres if isinstance(pres, dict) else None})
json.dump(S, open('state.json', 'w'))
json.dump(LOG, open('log_s5.json', 'w'), ensure_ascii=False, indent=1)
